import { Accordion as Base } from "@base-ui/react/accordion";
import { clsx as cn } from "clsx";
import styles from "./styles.module.css";

function Root({ className, ...props }: Base.Root.Props) {
  return <Base.Root className={cn(styles.root, className)} {...props} />;
}

function Item({ className, ...props }: Base.Item.Props) {
  return <Base.Item className={cn(styles.item, className)} {...props} />;
}

function Header({ className, ...props }: Base.Header.Props) {
  return <Base.Header className={cn(styles.header, className)} {...props} />;
}

function Trigger({ className, ...props }: Base.Trigger.Props) {
  return <Base.Trigger className={cn(styles.trigger, className)} {...props} />;
}

function Panel({ className, ...props }: Base.Panel.Props) {
  return <Base.Panel className={cn(styles.panel, className)} {...props} />;
}

export const Accordion = {
  Root,
  Item,
  Header,
  Trigger,
  Panel,
};

import { clsx as cn } from "clsx";
import type { ComponentProps } from "react";
import { Button, type ButtonProps } from "../../button";
import styles from "./styles.module.css";

function Root({ className, ...props }: ComponentProps<"div">) {
  return <div className={cn(styles.root, className)} {...props} />;
}

function Item({ className, ...props }: ComponentProps<"span">) {
  return <span className={cn(styles.item, className)} {...props} />;
}

function Thumb({ className, ...props }: ComponentProps<"span">) {
  return <span className={cn(styles.thumb, className)} {...props} />;
}

function Label({ className, ...props }: ComponentProps<"span">) {
  return <span className={cn(styles.label, className)} {...props} />;
}

function Remove({
  className,
  variant = "ghost",
  size = "xs",
  icon = true,
  ...props
}: ButtonProps) {
  return (
    <Button
      variant={variant}
      size={size}
      icon={icon}
      className={cn(styles.remove, className)}
      {...props}
    />
  );
}

export const Attachments = { Root, Item, Thumb, Label, Remove };

.root {
  display: flex;
  gap: 8px;
  align-items: center;
  padding: 6px 8px;
  margin-bottom: 8px;
  background: var(--ds-gray-2);
  border: var(--ds-border-width) solid var(--ds-border-subtle);
  border-radius: var(--ds-radius-xl);
}

.item {
  display: contents;
}

.thumb {
  display: inline-flex;
  flex-shrink: 0;
  width: 28px;
  height: 28px;
  overflow: hidden;
  border-radius: var(--ds-radius-sm);

  & img {
    width: 100%;
    height: 100%;
    object-fit: cover;
  }
}

.label {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  font-size: var(--ds-text-mini);
  font-weight: var(--ds-weight-medium);
  color: var(--ds-gray-11);
  white-space: nowrap;
}

.remove {
  flex-shrink: 0;
}

import { IconXmarkOutline12 as Clear } from "@pond/icons/outline/12";
import { clsx as cn } from "clsx";
import { forwardRef, type ReactNode } from "react";
import styles from "./styles.module.css";

export type ChipTone = "mention" | "tag";

type ChipProps = {
  tone: ChipTone;
  lead: ReactNode;
  label: string;
  title?: string;
  selected?: boolean;
  onRemove?: () => void;
  className?: string;
};

const Root = forwardRef<HTMLSpanElement, ChipProps>(function ChipRoot(
  { tone, lead, label, title, selected, onRemove, className },
  ref,
) {
  return (
    <span
      ref={ref}
      className={cn(styles.chip, className)}
      data-tone={tone}
      data-selected={selected || undefined}
      data-static={!onRemove || undefined}
      title={title ?? label}
    >
      <span className={styles.body}>
        <span className={styles.lead}>{lead}</span>
        <span className={styles.label}>{label}</span>
      </span>
      {onRemove ? (
        <button
          type="button"
          className={styles.remove}
          aria-label={`Remove ${label}`}
          onClick={onRemove}
          onMouseDown={(event) => event.preventDefault()}
        >
          <Clear />
        </button>
      ) : null}
    </span>
  );
});

export const Chip = { Root };

.chip {
  display: inline-flex;
  align-items: center;
  max-width: 240px;
  height: 22px;
  margin-inline: 1px;
  font-size: var(--ds-text-mini);
  font-weight: var(--ds-weight-medium);
  vertical-align: middle;
  color: var(--ds-gray-12);
  user-select: none;
  background: var(--ds-gray-a3);
  border-radius: var(--ds-radius-full);
}

.chip[data-selected] {
  box-shadow: 0 0 0 2px var(--ds-accent-a7);
}

.body {
  display: inline-flex;
  gap: 4px;
  align-items: center;
  min-width: 0;
  height: 100%;
  padding-inline: 7px 3px;
}

.chip[data-static] .body {
  padding-inline: 7px;
}

.lead {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  min-width: 12px;
  font-weight: var(--ds-weight-semibold);
  color: currentColor;
  opacity: 0.85;
}

.label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.remove {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 100%;
  padding: 0;
  color: var(--ds-gray-10);
  cursor: var(--ds-cursor-interactive, pointer);
  background: none;
  border: 0;
  border-radius: inherit;
  transition: color var(--ds-duration-fast) var(--ds-easing-standard);

  &:hover {
    color: var(--ds-gray-12);
  }
}

import { clsx as cn } from "clsx";
import type { ComponentProps } from "react";
import styles from "./styles.module.css";

function Root({ className, ...props }: ComponentProps<"div">) {
  return <div className={cn(styles.root, className)} {...props} />;
}

function Content({ className, ...props }: ComponentProps<"div">) {
