.root {
  position: relative;
  display: flex;
  flex: 1;
  flex-direction: column;
  min-height: 0;
  overflow: hidden;
}

.content {
  display: flex;
  flex-direction: column;
  gap: 16px;
  padding: 8px 3px 24px;
}

.empty {
  display: flex;
  flex: 1;
  flex-direction: column;
  align-items: flex-start;
  justify-content: flex-start;
  padding: 12px 4px 24px;
  font-size: var(--ds-text-body);
  font-weight: var(--ds-weight-normal);
  line-height: 1.6;
  color: var(--ds-gray-12);
}

.scroll-button {
  position: absolute;
  bottom: 8px;
  left: 50%;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  padding: 0;
  color: var(--ds-gray-11);
  cursor: var(--ds-cursor-interactive, pointer);
  outline: none;
  background: var(--ds-gray-3);
  border: 0;
  border-radius: var(--ds-radius-full);
  box-shadow: var(--ds-shadow-3);
  transform: translateX(-50%);
  transition: opacity var(--ds-duration-medium) var(--ds-easing-standard);

  &:hover {
    color: var(--ds-gray-12);
    background: var(--ds-gray-4);
  }

  &:focus-visible {
    outline: 2px solid var(--ds-gray-6);
    outline-offset: 2px;
  }

  &[inert] {
    opacity: 0;
  }
}

export { Attachments } from "./attachments";
export { Chip, type ChipTone } from "./chip";
export { Conversation } from "./conversation";
export { Loader } from "./loader";
export { Message } from "./message";
