import { clsx as cn } from "clsx";
import type { ComponentProps } from "react";
import styles from "./styles.module.css";

function Root({ className, ...props }: ComponentProps<"span">) {
  return (
    <span role="status" className={cn(styles.root, className)} {...props} />
  );
}

function Dots({ className, ...props }: ComponentProps<"span">) {
  return (
    <span className={cn(styles.dots, className)} aria-hidden {...props}>
      <span />
      <span />
      <span />
    </span>
  );
}

export const Loader = { Root, Dots };

.root {
  display: inline-flex;
  gap: 6px;
  align-items: baseline;
  font-size: var(--ds-text-mini);
  font-weight: var(--ds-weight-medium);
  color: var(--ds-gray-9);
}

.dots {
  display: inline-flex;
  gap: 5px;
  align-items: center;
  color: var(--ds-gray-12);
}

.dots > span {
  width: 7px;
  height: 7px;
  background: currentColor;
  border-radius: var(--ds-radius-full);
  animation: loader-dot 1.4s ease-in-out infinite;
}

.dots > span:nth-child(2) {
  animation-delay: 0.2s;
}

.dots > span:nth-child(3) {
  animation-delay: 0.4s;
}

@keyframes loader-dot {
  0%,
  80%,
  100% {
    opacity: 0.28;
  }

  40% {
    opacity: 1;
  }
}

@media (prefers-reduced-motion: reduce) {
  .dots > span {
    opacity: 0.55;
    animation: none;
  }
}

