import { AlertDialog as Base } from "@base-ui/react/alert-dialog";
import { clsx as cn } from "clsx";
import { Content, Footer, Header } from "../shared/parts/dialog";
import styles from "../shared/styles/dialog/styles.module.css";

function Root<Payload = unknown>(props: Base.Root.Props<Payload>) {
  return <Base.Root {...props} />;
}

function Trigger(props: Base.Trigger.Props) {
  return <Base.Trigger {...props} />;
}

function Portal(props: Base.Portal.Props) {
  return <Base.Portal {...props} />;
}

function Backdrop({ className, ...props }: Base.Backdrop.Props) {
  return (
    <Base.Backdrop className={cn(styles.backdrop, className)} {...props} />
  );
}

function Popup({ className, ...props }: Base.Popup.Props) {
  return <Base.Popup {...props} className={cn(styles.popup, className)} />;
}

function Title({ className, ...props }: Base.Title.Props) {
  return <Base.Title className={cn(styles.title, className)} {...props} />;
}

function Description({ className, ...props }: Base.Description.Props) {
  return (
    <Base.Description
      className={cn(styles.description, className)}
      {...props}
    />
  );
}

function Close(props: Base.Close.Props) {
  return <Base.Close {...props} />;
}

function Viewport(props: Base.Viewport.Props) {
  return <Base.Viewport {...props} />;
}

export const AlertDialog = {
  Root,
  Trigger,
  Portal,
  Backdrop,
  Popup,
  Title,
  Description,
  Header,
  Content,
  Footer,
  Close,
  Viewport,
  createHandle: Base.createHandle,
  Handle: Base.Handle,
};

import { Button as Base } from "@base-ui/react/button";
import { clsx as cn } from "clsx";
import styles from "./styles.module.css";

export interface ButtonProps extends Base.Props {
  variant?:
    | "primary"
    | "secondary"
    | "tertiary"
    | "ghost"
    | "accent"
    | "destructive"
    | "link";
  size?: "xs" | "sm" | "md" | "lg" | "xl";
  icon?: boolean;
  width?: "full" | "auto";
}

export function Button({
  className,
  variant = "primary",
  size = "md",
  width = "auto",
  icon,
  ...props
}: ButtonProps) {
  return (
    <Base
      data-width={width}
      data-variant={variant}
      data-size={size}
      data-icon={icon ? "" : undefined}
      className={cn(styles.root, className)}
      {...props}
    />
  );
}

.root {
  --button-height-xs: 24px;
  --button-padding-xs: 0 8px;
  --button-font-size-xs: var(--ds-text-micro);
  --button-radius-xs: var(--ds-radius-full);
  --button-height-sm: 28px;
  --button-padding-sm: 0 12px;
  --button-font-size-sm: var(--ds-text-mini);
  --button-radius-sm: var(--ds-radius-full);
  --button-height-md: 32px;
  --button-padding-md: 0 12px;
  --button-font-size-md: var(--ds-text-small);
  --button-radius-md: var(--ds-radius-full);
  --button-height-lg: 36px;
  --button-padding-lg: 0 16px;
  --button-font-size-lg: var(--ds-text-small);
  --button-radius-lg: var(--ds-radius-full);
  --button-height-xl: 44px;
  --button-padding-xl: 0 24px;
  --button-font-size-xl: var(--ds-text-body);
  --button-radius-xl: var(--ds-radius-full);
}

.root {
  display: inline-flex;
  gap: 6px;
  align-items: center;
  justify-content: center;
  font-weight: var(--ds-weight-medium);
  line-height: 1;
  text-wrap: nowrap;
  user-select: none;
  transition: all var(--ds-duration-medium) var(--ds-easing-standard);

  &:where([data-width="full"]) {
    width: 100%;
  }

  &:where([data-width="auto"]) {
    width: fit-content;
  }

  &:where([data-disabled]),
  &:where([data-loading]) {
    cursor: not-allowed;
    opacity: 0.5;
  }

  &:active {
    scale: 0.98;
  }

  &:focus-visible,
  &[data-demo-state="focus"] {
    outline-width: 2px;
    outline-style: solid;
    outline-offset: 2px;
  }

  &:where([data-size="xs"]) {
    height: var(--button-height-xs);
    padding: var(--button-padding-xs);
    font-size: var(--button-font-size-xs);
    border-radius: var(--button-radius-xs);
  }

  &:where([data-size="sm"]) {
    height: var(--button-height-sm);
    padding: var(--button-padding-sm);
    font-size: var(--button-font-size-sm);
    border-radius: var(--button-radius-sm);
  }

  &:where([data-size="md"]) {
    height: var(--button-height-md);
    padding: var(--button-padding-md);
    font-size: var(--button-font-size-md);
    border-radius: var(--button-radius-md);
  }

  &:where([data-size="lg"]) {
    height: var(--button-height-lg);
    padding: var(--button-padding-lg);
    font-size: var(--button-font-size-lg);
    border-radius: var(--button-radius-lg);
  }

  &:where([data-size="xl"]) {
    height: var(--button-height-xl);
    padding: var(--button-padding-xl);
    font-size: var(--button-font-size-xl);
    border-radius: var(--button-radius-xl);
  }

  &:where([data-icon]) {
    aspect-ratio: 1 / 1;

    &:where([data-size="xs"]) {
      padding: 4px;
    }

    &:where([data-size="sm"]) {
      padding: 6px;
    }

    &:where([data-size="md"]) {
      padding: 8px;
    }

    &:where([data-size="lg"]) {
      padding: 10px;
    }
  }

  &:where([data-variant="primary"]) {
    color: var(--ds-gray-1);
    background:
      linear-gradient(var(--ds-white-a2) 0%, var(--ds-white-a1) 100%),
      var(--ds-gray-12);

    &:hover,
    &[data-demo-state="hover"] {
      opacity: 0.8;
    }

    &:focus-visible,
    &[data-demo-state="focus"] {
      outline-color: var(--ds-gray-6);
    }
  }

  &:where([data-variant="secondary"]) {
    color: var(--ds-gray-12);
    background-color: var(--ds-gray-1);
    box-shadow: var(--ds-shadow-1);

    &:hover,
    &[data-demo-state="hover"] {
      background-color: var(--ds-gray-2);
      box-shadow: var(--ds-shadow-2);
    }

    &:focus-visible,
    &[data-demo-state="focus"] {
      outline-color: var(--ds-gray-6);
    }
  }

  &:where([data-variant="tertiary"]) {
    color: var(--ds-gray-11);
    background-color: var(--ds-gray-a3);

    &:hover,
    &[data-demo-state="hover"] {
      color: var(--ds-gray-12);
