}

.sort-button:hover,
.sort-button[data-active] {
  color: var(--ds-gray-12);
}

.sort-caret {
  color: var(--ds-gray-9);
  transform: rotate(180deg);
}

.sort-caret[data-desc] {
  transform: none;
}

.body {
  min-width: 0;
}

.row {
  display: grid;
  align-items: center;
  min-height: 34px;
  cursor: var(--ds-cursor-interactive, pointer);
  border-radius: var(--ds-radius-md);
  transition: background var(--ds-duration-fast, 0.12s) ease;
}

.row:hover,
.row:focus-visible {
  outline: none;
  background: var(--ds-gray-2);
}

.row[data-selected] {
  background: var(--ds-accent-a1);
  border-radius: 0;
}

.row[data-selected][data-selected-start] {
  border-top-left-radius: var(--ds-radius-md);
  border-top-right-radius: var(--ds-radius-md);
}

