  padding: 0 12px;
}

.cell[data-align="end"] {
  justify-content: flex-end;
}

.cell[data-align="center"] {
  justify-content: center;
}

.select-cell,
.caret-cell {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100%;
  padding: 0;
}

.check {
  flex: none;
  scale: 0.8;
}

.caret {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  width: 16px;
  height: 16px;
  padding: 0;
  color: var(--ds-gray-10);
  cursor: var(--ds-cursor-interactive, pointer);
  background: transparent;
  border: 0;
  transition: transform var(--ds-duration-fast, 0.12s) ease;
}

.caret[data-open] {
  transform: rotate(90deg);
}

.action-bar {
  position: fixed;
  bottom: 24px;
  left: 50%;
  z-index: 50;
  display: flex;
  gap: 6px;
  align-items: center;
  padding: 7px 8px 7px 14px;
  background: var(--ds-gray-1);
  border-radius: var(--ds-radius-full, 999px);
  box-shadow: var(--ds-shadow-3);
  transform: translateX(calc(-50% + var(--data-table-action-bar-offset, 0px)));
  animation: data-table-action-bar-in var(--ds-duration-fast, 0.16s) ease;
}

.action-bar-divider {
  width: 1px;
  height: 18px;
  margin: 0 2px;
  background: var(--ds-gray-a5);
}

@keyframes data-table-action-bar-in {
  from {
    opacity: 0;
    transform: translate(
      calc(-50% + var(--data-table-action-bar-offset, 0px)),
      8px
    );
  }

  to {
    opacity: 1;
    transform: translate(
      calc(-50% + var(--data-table-action-bar-offset, 0px)),
      0
    );
  }
}

@media (prefers-reduced-motion: reduce) {
  .action-bar {
    animation: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .caret,
  .row {
    transition: none;
  }
}

