type InputSize = "xs" | "sm" | "md" | "lg" | "xl";
type InputVariant = "primary" | "secondary";

function Root({
  className,
  size = "md",
  variant = "primary",
  ...props
}: React.ComponentProps<"div"> & { size?: InputSize; variant?: InputVariant }) {
  return (
    <div
      data-slot="root"
      data-size={size}
      data-variant={variant}
      className={cn(styles.root, className)}
      {...props}
    />
  );
}

function Icon({ className, ...props }: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="icon"
      aria-hidden="true"
      className={cn(styles.icon, className)}
      {...props}
    />
  );
}

function Field({ className, ...props }: Base.Props) {
  return (
    <Base
      data-slot="field"
      className={cn(styles.field, className)}
      {...props}
    />
  );
}

const Textarea = forwardRef<
  HTMLTextAreaElement,
  React.ComponentProps<"textarea"> & {
    onValueChange?: (value: string) => void;
  }
>(function Textarea(
  { className, rows = 5, onChange, onValueChange, ...props },
  ref,
) {
  return (
    <textarea
      {...props}
      ref={ref}
      data-slot="field"
      data-multiline
      rows={rows}
      className={cn(styles.field, className)}
      onChange={(event) => {
        onChange?.(event);
        onValueChange?.(event.target.value);
      }}
    />
  );
});

export const Input = { Root, Icon, Field, Textarea };

