function Input({ className, onKeyDown, ...props }: BaseInput.Props) {
  return (
    <BaseInput
      type="search"
      spellCheck={false}
      className={cn(styles.input, className)}
      onKeyDown={(event) => {
        onKeyDown?.(event);
        if (
          event.key.length === 1 &&
          !event.ctrlKey &&
          !event.metaKey &&
          !event.altKey
        ) {
          event.stopPropagation();
        }
      }}
      {...props}
    />
  );
}

