.root {
  --window-inset: 16px;
  --window-radius: var(--ds-radius-xl);
  --window-ring: 1px;
  --window-chrome-start: 12px;
  /* Traffic-light padding plus the four 28px titlebar controls. */
  --window-left-min: calc(var(--window-chrome-start) + 28px * 4 + 2px * 3);
  --window-right-width: 0px;
  --window-right-inset: 0px;
  --window-left-width: var(--window-left-min);
  --window-right-track: 352px;
  --window-left-track: 352px;
  --window-background-primary: var(--ds-gray-2);
  --window-background-secondary: var(--ds-gray-1);
  --window-edge-duration: var(--ds-duration-medium);
  --window-edge-easing: var(--ds-easing-decelerate);

  position: relative;
  display: grid;
  grid-template-rows: auto 1fr auto;
  grid-template-columns: auto 1fr auto;
  grid-template-areas:
    "top top top"
    "left center right"
    "bottom bottom bottom";
  width: 100%;
  height: 100%;
  min-height: 0;
  overflow: hidden;
  background: var(--window-background-primary);
  interpolate-size: allow-keywords;
  transition:
    --window-left-width var(--window-edge-duration) var(--window-edge-easing),
    --window-right-width var(--window-edge-duration) var(--window-edge-easing),
    --window-right-inset var(--window-edge-duration) var(--window-edge-easing);
}

.root[data-right-open] {
  --window-right-width: var(--window-right-track);
  --window-right-inset: var(--window-inset);
}

.root[data-left-open] {
  --window-left-width: var(--window-left-track);
}

.top {
  z-index: 2;
  grid-area: top;
  flex-shrink: 0;
  height: 0;
  overflow: hidden;
  background: transparent;
  opacity: 0;
  transition:
    height var(--window-edge-duration) var(--window-edge-easing),
    opacity var(--window-edge-duration) var(--window-edge-easing);
  -webkit-app-region: drag;
}

.top[data-open] {
  height: auto;
  overflow: visible;
  opacity: 1;
}

.left,
.right {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;
  /* Clip the closed track so the absolute card cannot paint over Center. */
  overflow: hidden;
  pointer-events: none;
}

.left {
  grid-area: left;
  width: var(--window-left-width);
  min-width: var(--window-left-min);
  margin-bottom: var(--window-inset);
}

.right {
  grid-area: right;
  width: var(--window-right-width);
  margin-right: var(--window-right-inset);
  margin-bottom: var(--window-inset);
}

.left[data-open],
.right[data-open] {
  overflow: visible;
  pointer-events: auto;
}

.edge-content {
  position: absolute;
  inset-block: 0;
  min-height: 0;
  contain: layout;
  opacity: 0;
  transition:
    opacity var(--ds-duration-fast) var(--ds-easing-standard),
    transform var(--ds-duration-snap) var(--ds-easing-decelerate);
}

.left > .edge-content {
  left: 0;
  width: var(--window-left-track);
  min-width: var(--window-left-track);
  transform: translateX(-6px);
}

.right > .edge-content {
  inset: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  background: var(--window-background-secondary);
  border-radius: var(--window-radius);
  box-shadow: var(--ds-shadow-1);
  transform: translateX(6px);
}

.left[data-open] > .edge-content,
.right[data-open] > .edge-content {
  opacity: 1;
  transform: translateX(0);
  transition-delay: var(--ds-duration-fast), 0ms;
}

.center {
  --ring: linear-gradient(to right, var(--ds-accent-9), transparent 8.65%);

  position: relative;
  display: flex;
  flex-direction: column;
  grid-area: center;
  min-width: 0;
  min-height: 0;
  margin-right: var(--window-inset);
  margin-bottom: var(--window-inset);
  margin-left: var(--window-inset);
  overflow: hidden;
  background: var(--window-background-secondary);
  border-radius: var(--window-radius);
  box-shadow: var(--ds-shadow-1);
}

.center::after {
  position: absolute;
  inset: 0;
  z-index: 4;
  pointer-events: none;
  content: "";
  background: var(--ring) border-area;
  border: var(--window-ring) solid transparent;
  border-radius: inherit;
  opacity: 0;
  transition: opacity var(--ds-duration-fast, 0.12s) ease;
}

.handle {
  position: absolute;
  top: 0;
  z-index: 3;
  width: 8px;
  height: 100%;
  margin: 0;
  border: 0;
  touch-action: none;
  cursor: col-resize;
  -webkit-app-region: no-drag;

  &[data-edge="left"] {
    left: 0;
  }

  &[data-edge="right"] {
    right: 0;
  }
}

.center:has(.handle[data-edge="left"]:hover)::after,
.root[data-resizing="left"] .center::after,
.center:has(.handle[data-edge="right"]:hover)::after,
.root[data-resizing="right"] .center::after {
  opacity: 1;
}

.center:has(.handle[data-edge="right"]:hover),
.root[data-resizing="right"] .center {
  --ring: linear-gradient(to left, var(--ds-accent-9), transparent 8.65%);
}

@supports not (background-clip: border-area) {
  .center::after {
    padding: var(--window-ring);
    background: var(--ring);
    border: 0;
    -webkit-mask:
      linear-gradient(#000 0 0) content-box,
      linear-gradient(#000 0 0);
    mask:
      linear-gradient(#000 0 0) content-box,
      linear-gradient(#000 0 0);
    -webkit-mask-composite: xor;
    mask-composite: exclude;
  }
}

.hint {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.left[data-resizing],
.right[data-resizing],
.root[data-resizing],
.root[data-resizing] .left,
.root[data-resizing] .right {
  transition: none;
}

.bottom {
  grid-area: bottom;
  height: 0;
  padding-right: var(--window-inset);
  padding-left: var(--window-inset);
  overflow: hidden;
  opacity: 0;
  transition:
    height var(--window-edge-duration) var(--window-edge-easing),
    opacity var(--window-edge-duration) var(--window-edge-easing);
}

.bottom[data-open] {
  height: auto;
  opacity: 1;
}

@media (prefers-reduced-motion: reduce) {
  .root,
  .top,
  .left,
  .right,
  .edge-content,
  .bottom {
    transition: none;
  }
}

